'use strict';
tr.daily57='Việc cần làm hôm nay';tr.soc51='SOC Dashboard';tr.endpoint58='Endpoint Monitoring';tr.vuln51='Vulnerability Center';tr.siem51='SIEM / Alerts';tr.crypto51='Mã hóa & Password';tr.vault51='Secret Vault';tr.secpost51='Security Posture';tr.compliance53='Compliance & Response';tr.threat54='Threat Intel & Detection';tr.cases55='Cases & Asset Risk';tr.notify56='Notifications & Reports';
navIcon.daily57='☑';navIcon.soc51='⬢';navIcon.endpoint58='▣';navIcon.vuln51='⌁';navIcon.siem51='⚠';navIcon.crypto51='◆';navIcon.vault51='▣';navIcon.secpost51='盾';navIcon.compliance53='✓';navIcon.threat54='◎';navIcon.cases55='▤';navIcon.notify56='✉';
const socGroup=groups.find(g=>g[0]==='AN NINH & SOC');if(socGroup){for(const p of ['daily57','soc51','endpoint58','cases55','vuln51','siem51','threat54'])if(!socGroup[1].includes(p))socGroup[1].push(p)}
const govGroup=groups.find(g=>g[0]==='TUÂN THỦ & PHẢN ỨNG');if(govGroup){for(const p of ['compliance53','notify56','secpost51'])if(!govGroup[1].includes(p))govGroup[1].push(p)}
const adminGroup=groups.find(g=>g[0]==='QUẢN TRỊ HỆ THỐNG');if(adminGroup){for(const p of ['vault51','crypto51'])if(!adminGroup[1].includes(p))adminGroup[1].push(p)}
function cyberWrite(){return ['Admin','Analyst','Operator'].includes(state.user?.role)}
function cyberSeverity(v){return badge(String(v||'INFO').toUpperCase())}
function cyberDetails(obj){return `<pre class="crypto-output">${esc(JSON.stringify(obj,null,2))}</pre>`}

// v5.1 replaces password-only login with password + mandatory TOTP enrollment/verification.

actions['register-open']=async()=>{
  modal('Đăng ký tài khoản',`<form id="register-form" class="form-grid"><p class="caption">Tài khoản tự đăng ký có quyền <b>Viewer</b>. Mật khẩu tối thiểu 12 ký tự.</p><label>Tài khoản<input name="username" maxlength="64" autocomplete="username" required placeholder="Ví dụ: nguyenvana"></label><label>Mật khẩu<input name="password" type="password" minlength="12" maxlength="256" autocomplete="new-password" required placeholder="Tối thiểu 12 ký tự"></label><label>Xác nhận mật khẩu<input name="confirmation" type="password" minlength="12" maxlength="256" autocomplete="new-password" required placeholder="Nhập lại mật khẩu"></label><div id="register-error" class="error hidden" role="alert"></div><div><button type="submit" class="primary">Tạo tài khoản</button> <button type="button" data-action="close-modal">Hủy</button></div></form>`);
  setTimeout(()=>$('#dialog input[name=username]')?.focus(),50);
};
forms['register-form']=async f=>{
  const v=vals(f),err=$('#register-error');
  if(err){err.textContent='';err.classList.add('hidden')}
  if(v.password!==v.confirmation)throw new Error('PASSWORD_CONFIRMATION_MISMATCH');
  const r=await api('/auth/register',{method:'POST',body:JSON.stringify(v)});
  $('#dialog').close();
  const login=$('#login-form');if(login){login.elements.username.value=r.username||v.username;login.elements.password.value='';}
  toast(r.enabled?'Đăng ký thành công. Bạn có thể đăng nhập ngay.':'Đăng ký thành công. Tài khoản đang chờ Admin kích hoạt.');
  setTimeout(()=>$('#login-form input[name=password]')?.focus(),50);
};

forms['login-form']=async f=>{const err=$('#login-error');if(err){err.textContent='';err.classList.add('hidden')}const r=await api('/auth/login',{method:'POST',body:JSON.stringify(vals(f))});if(r.mfa_enroll_required){modal('Thiết lập MFA',`<div class="mfa-login-panel"><p class="mfa-help">Mật khẩu đã đúng. Chính sách hiện tại yêu cầu hoàn tất MFA. Thêm khóa dưới đây vào Google/Microsoft Authenticator, chờ mã 6 số mới rồi xác thực.</p><div class="mfa-secret">${esc(r.secret)}</div><details><summary>URI cấu hình Authenticator</summary><pre class="crypto-output">${esc(r.otpauth_uri)}</pre></details><form id="mfa-login-form" class="form-grid"><input type="hidden" name="challenge" value="${esc(r.challenge)}"><label>Mã Authenticator 6 số<input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" minlength="6" maxlength="6" required placeholder="000000"></label><div id="mfa-error" class="error mfa-inline-error hidden" role="alert"></div><div><button type="submit" class="primary">Bật MFA & đăng nhập</button> <button type="button" data-action="close-modal">Hủy</button></div></form></div>`);setTimeout(()=>$('#dialog input[name=code]')?.focus(),50);return}if(r.mfa_required){modal('Xác thực đa yếu tố',`<div class="mfa-login-panel"><p class="mfa-help">Tài khoản này đang bật MFA. Nhập mã 6 số hiện tại trong ứng dụng Authenticator. Nếu mã sắp đổi, chờ mã kế tiếp rồi nhập.</p><form id="mfa-login-form" class="form-grid"><input type="hidden" name="challenge" value="${esc(r.challenge)}"><label>Mã Authenticator 6 số<input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" minlength="6" maxlength="6" required placeholder="000000"></label><div id="mfa-error" class="error mfa-inline-error hidden" role="alert"></div><div><button type="submit" class="primary">Xác thực & đăng nhập</button> <button type="button" data-action="close-modal">Hủy</button></div></form></div>`);setTimeout(()=>$('#dialog input[name=code]')?.focus(),50);return}f.reset();state.csrf=r.csrf_token;await loggedIn()};
forms['mfa-login-form']=async f=>{const v=vals(f);v.code=String(v.code||'').replace(/\D/g,'').slice(0,6);if(v.code.length!==6)throw new Error('Mã MFA phải gồm đúng 6 chữ số.');const r=await api('/auth/mfa/verify',{method:'POST',body:JSON.stringify(v)});state.csrf=r.csrf_token;$('#dialog').close();$('#login-form')?.reset();await loggedIn()};

pages.soc51=async()=>{const d=await api('/v51/dashboard');return `<div class="cyber-hero"><div><div class="eyebrow">CYBERSECURITY OPERATIONS / 5.8</div><h2>Security Operations Center</h2><p class="muted">Tổng hợp tài sản, sự kiện SIEM, cảnh báo, lỗ hổng và đăng nhập bất thường. Các phép quét chủ động chỉ chạy với tài sản private đã được đăng ký.</p><div class="toolbar">${button('Việc cần làm hôm nay','page',{page:'daily57'},'primary')}${button('Endpoint Monitoring','page',{page:'endpoint58'})}${button('Cases & Asset Risk','page',{page:'cases55'})}${button('Notifications & Reports','page',{page:'notify56'})}${button('Vulnerability Center','page',{page:'vuln51'})}${button('SIEM / Alerts','page',{page:'siem51'})}${button('Threat Intel & Detection','page',{page:'threat54'})}${button('Compliance & Response','page',{page:'compliance53'})}${button('Security Posture','page',{page:'secpost51'})}</div></div><div class="score"><strong>${esc(d.security_score)}</strong><small>Security Score / 100</small></div></div><div class="cyber-grid"><div class="cyber-card"><small>Assets</small><strong>${esc(d.assets)}</strong></div><div class="cyber-card"><small>Open alerts</small><strong>${esc(d.open_alerts)}</strong></div><div class="cyber-card"><small>Critical / High</small><strong>${esc(d.critical_alerts)} / ${esc(d.high_alerts)}</strong></div><div class="cyber-card"><small>Failed logins 24h</small><strong>${esc(d.failed_logins_24h)}</strong></div><div class="cyber-card"><small>Vulnerability findings</small><strong>${esc(d.vulnerability_findings)}</strong></div><div class="cyber-card"><small>Open incidents</small><strong>${esc(d.open_incidents)}</strong></div></div><div class="grid2">${panel('Cảnh báo ưu tiên',table(d.alerts,[['Mức','severity',cyberSeverity],['Tiêu đề','title'],['Asset','asset_ip'],['User','subject_user'],['Count','count'],['Last seen','last_seen']]))}${panel('SIEM gần đây',table(d.events,[['Mức','severity',cyberSeverity],['Nguồn','source'],['Loại','event_type'],['Thông điệp','message'],['Asset','asset_ip'],['Time','created_at']]))}</div>`};

pages.vuln51=async()=>{const [assets,findings]=await Promise.all([api('/v45/ipmac'),api('/v51/vulnerability/findings?limit=1000')]);const ips=[...new Set(assets.map(x=>x.ip).filter(Boolean))];const opts=ips.map(x=>[x,x]);return panel('Defensive Vulnerability Assessment',`<p class="scan-note">Chỉ TCP-connect scan tối đa 32 cổng trên tài sản IPv4 private đã có trong inventory. Không exploit, không brute-force, không thử credential.</p>${cyberWrite()&&opts.length?form('vuln-scan51-form',select('Asset IP','asset_ip',opts)+input('Ports, ví dụ 22,80,443,3389','ports','text','22,23,80,443,445,3389',false)+input('Timeout ms','timeout_ms','number',500),'Quét an toàn'):empty('Chưa có security asset để quét. Hãy đồng bộ/khám phá tài sản trước.')}`)+panel('Kết quả phát hiện',table(findings,[['Time','created_at'],['Asset','asset_ip'],['Port','port'],['Service','service'],['Mức','severity',cyberSeverity],['Finding','finding']]))+panel('CVE Lookup (NVD)',isAdmin()||isAnalyst()?form('cve-lookup51-form',input('CVE ID','cve_id','text','CVE-2024-'),'Tra cứu NVD'):'<p class="caption">Admin/Analyst có thể tra cứu CVE.</p>')+`<div id="cve-result51"></div>`};
forms['vuln-scan51-form']=async f=>{const v=vals(f),ports=String(v.ports||'').split(',').map(x=>Number(x.trim())).filter(x=>Number.isInteger(x)&&x>0);const r=await api('/v51/vulnerability/scan',{method:'POST',body:JSON.stringify({asset_ip:v.asset_ip,ports,timeout_ms:Number(v.timeout_ms||500)})});modal('Vulnerability scan #'+r.scan_id,`<div class="cards">${metric('Open ports',r.open_ports.length)}${metric('Findings',r.findings.length)}</div>${table(r.findings,[['Port','port'],['Service','service'],['Severity','severity',cyberSeverity],['Finding','finding']])}<p class="caption">${esc(r.note)}</p>`);await go('vuln51')};
forms['cve-lookup51-form']=async f=>{const r=await api('/v51/vulnerability/cve/lookup',{method:'POST',body:JSON.stringify(vals(f))});const h=$('#cve-result51');if(h)h.innerHTML=panel('NVD result',cyberDetails(r))};

pages.siem51=async()=>{const [events,alerts]=await Promise.all([api('/v51/siem/events?limit=500'),api('/v51/alerts?status=ALL&limit=500')]);const open=alerts.filter(x=>x.status!=='RESOLVED');return `<div class="cyber-grid"><div class="cyber-card"><small>Events loaded</small><strong>${events.length}</strong></div><div class="cyber-card"><small>Active alerts</small><strong>${open.length}</strong></div><div class="cyber-card"><small>Acknowledged</small><strong>${alerts.filter(x=>x.status==='ACKNOWLEDGED').length}</strong></div><div class="cyber-card"><small>Resolved</small><strong>${alerts.filter(x=>x.status==='RESOLVED').length}</strong></div></div>`+panel('SOC Alerts',table(alerts,[['Mức','severity',cyberSeverity],['Status','status',badge],['Rule','rule_key'],['Title','title'],['Asset','asset_ip'],['Owner','owner'],['Count','count'],['Last','last_seen']],r=>{if(r.status==='RESOLVED')return (isAdmin()||isAnalyst())?button('Mở lại','soc-reopen51',{id:r.id}):'';const a=cyberWrite()?button('Nhận xử lý','soc-ack51',{id:r.id}):'';const z=(isAdmin()||isAnalyst())?button('Resolve','soc-resolve51',{id:r.id},'primary'):'';return a+z}))+panel('SIEM Events',table(events,[['Time','created_at'],['Mức','severity',cyberSeverity],['Source','source'],['Type','event_type'],['Asset','asset_ip'],['User','subject_user'],['Peer IP','peer_ip'],['Message','message']]))+(cyberWrite()?panel('Ghi sự kiện từ nguồn được ủy quyền',form('siem-event51-form',input('Source','source','text','manual')+input('Event type','event_type','text','SECURITY_EVENT')+select('Severity','severity',['INFO','LOW','MEDIUM','HIGH','CRITICAL'],'INFO')+input('Asset IP','asset_ip','text','',false)+input('Subject user','subject_user','text','',false)+input('Peer IP','peer_ip','text','',false)+input('Message','message','text'),'Ghi SIEM event')):'')};
forms['siem-event51-form']=async f=>{const v=vals(f);await api('/v51/siem/events',{method:'POST',body:JSON.stringify({...v,metadata:{source:'web-console'}})});toast('Đã ghi SIEM event và chạy correlation');await go('siem51')};
actions['soc-ack51']=async b=>{await api('/v51/alerts/'+b.dataset.id+'/ack',{method:'POST',body:JSON.stringify({note:'',owner:state.user?.username||''})});toast('Đã nhận xử lý cảnh báo');await go('siem51')};
actions['soc-resolve51']=async b=>{const note=prompt('Ghi chú xử lý / nguyên nhân / kết quả:','');if(note===null)return;await api('/v51/alerts/'+b.dataset.id+'/resolve',{method:'POST',body:JSON.stringify({note,owner:state.user?.username||''})});toast('Đã resolve cảnh báo');await go('siem51')};
actions['soc-reopen51']=async b=>{if(!confirm('Mở lại cảnh báo này?'))return;await api('/v51/alerts/'+b.dataset.id+'/reopen',{method:'POST',body:'{}'});toast('Đã mở lại cảnh báo');await go('siem51')};

pages.vault51=async()=>{if(!(isAdmin()||isAnalyst()))return panel('Enterprise Secret Vault','<p class="caption">Chức năng này dành cho Admin/Analyst. Viewer/Operator không được đọc metadata của vault.</p>');const rows=await api('/v51/vault');return panel('Enterprise Secret Vault',`<p class="caption">Secret được mã hóa bằng khóa credential hiện có. Danh sách không trả secret. Reveal chỉ dành cho Admin và yêu cầu mã TOTP hiện tại.</p>${isAdmin()?form('vault-create51-form',input('Tên','name')+input('Nhóm','category','text','General')+input('Username','username','text','',false)+input('Secret / Password','secret','password')+input('URL / hệ thống','url','text','',false)+input('Ghi chú','note','text','',false),'Lưu secret mã hóa'):'<p class="caption">Analyst chỉ xem metadata; Admin quản lý và reveal secret.</p>'}`)+panel('Secret metadata',table(rows,[['Nhóm','category'],['Tên','name'],['Username','username'],['URL','url'],['Owner','owner'],['Updated','updated_at'],['Last accessed','last_accessed_at']],r=>isAdmin()?button('Reveal','vault-reveal51',{id:r.id})+button('Xóa','vault-delete51',{id:r.id},'danger'):''))};
forms['vault-create51-form']=async f=>{await api('/v51/vault',{method:'POST',body:JSON.stringify(vals(f))});f.reset();toast('Đã lưu secret mã hóa');await go('vault51')};
actions['vault-reveal51']=async b=>{const code=prompt('Nhập mã TOTP 6 số hiện tại để xác nhận truy cập secret:','');if(!code)return;const r=await api('/v51/vault/'+b.dataset.id+'/reveal',{method:'POST',body:JSON.stringify({code})});modal('Secret · '+esc(r.name),`<p><b>Username:</b> ${esc(r.username||'—')}</p><textarea class="crypto-output" readonly rows=4>${esc(r.secret)}</textarea><p class="caption">Secret chỉ được trả về sau MFA step-up. Không được ghi vào audit log.</p>`)};
actions['vault-delete51']=async b=>{if(!confirm('Xóa secret này khỏi vault? Không thể hoàn tác.'))return;await api('/v51/vault/'+b.dataset.id,{method:'DELETE'});toast('Đã xóa secret');await go('vault51')};

pages.crypto51=async()=>panel('Password Strength',`<p class="caption">Mật khẩu chỉ được đánh giá trong request hiện tại; endpoint không ghi mật khẩu vào log/database.</p>${form('password-strength51-form',input('Mật khẩu cần kiểm tra','password','password'),'Kiểm tra độ mạnh')}<div id="password-strength51-result"></div>`)+panel('AES-256-GCM Text Encryption',`<p class="caption">Mã hóa/giải mã cục bộ trên server bằng AES-256-GCM + scrypt. Passphrase và plaintext không được lưu.</p>${form('crypto-encrypt51-form',input('Plaintext','plaintext','text')+input('Passphrase (12+ ký tự)','passphrase','password'),'Mã hóa')}<div id="crypto51-result"></div>`)+panel('Giải mã package',form('crypto-decrypt51-form',input('Encrypted package','package','text')+input('Passphrase','passphrase','password'),'Giải mã')+`<div id="decrypt51-result"></div>`)+(isAdmin()||isAnalyst()?panel('VirusTotal SHA-256 Reputation',form('hash-lookup51-form',input('SHA-256','sha256','text'),'Tra cứu hash')+`<div id="hash51-result"></div>`):'');
forms['password-strength51-form']=async f=>{const r=await api('/v51/password-strength',{method:'POST',body:JSON.stringify(vals(f))});$('#password-strength51-result').innerHTML=panel('Kết quả',`<div class="cards">${metric('Score',r.score+'/'+r.max_score)}${metric('Mức',r.label)}</div>${r.recommendations.length?'<ul>'+r.recommendations.map(x=>`<li>${esc(x)}</li>`).join('')+'</ul>':'<p>Không có khuyến nghị bổ sung.</p>'}`)};
forms['crypto-encrypt51-form']=async f=>{const r=await api('/v51/crypto/encrypt',{method:'POST',body:JSON.stringify(vals(f))});$('#crypto51-result').innerHTML=panel('Encrypted package',`<textarea class="crypto-output" readonly rows="6">${esc(r.package)}</textarea><p class="caption">${esc(r.algorithm)} · stored=${esc(r.stored)}</p>`)};
forms['crypto-decrypt51-form']=async f=>{const r=await api('/v51/crypto/decrypt',{method:'POST',body:JSON.stringify(vals(f))});$('#decrypt51-result').innerHTML=panel('Plaintext',`<pre class="crypto-output">${esc(r.plaintext)}</pre>`)};
forms['hash-lookup51-form']=async f=>{const r=await api('/v51/threat/hash-lookup',{method:'POST',body:JSON.stringify(vals(f))});$('#hash51-result').innerHTML=panel('VirusTotal result',cyberDetails(r))};

pages.secpost51=async()=>{const [posture,mfa,net,traffic,users]=await Promise.all([api('/v51/security-posture'),api('/v51/auth/mfa/status'),api('/v51/network/posture'),api('/v51/network/traffic'),isAdmin()?api('/v51/users/security'):Promise.resolve([])]);return `<div class="cyber-grid"><div class="cyber-card"><small>MFA</small><strong>${mfa.enabled?'ON':'SETUP'}</strong></div><div class="cyber-card"><small>Policy</small><strong>${mfa.required?'REQUIRED':'OPTIONAL'}</strong></div><div class="cyber-card"><small>Network</small><strong>${esc(net.mode||'—')}</strong></div><div class="cyber-card"><small>VPN indicator</small><strong>${net.vpn_detected?'YES':'NO'}</strong></div></div>`+panel('Application Security Controls',posture.checks.map(x=>`<div class="security-control ${String(x.status).toLowerCase()}"><b>${esc(x.control)} — ${esc(x.status)}</b><div class="caption">${esc(x.evidence)}</div></div>`).join('')+`<p class="caption">${esc(posture.principles.join(' · '))}</p>`)+panel('Network Security Posture',`<div class="cyber-kv"><div><b>IPv4</b><span>${esc(net.ipv4||'—')}</span></div><div><b>Subnet</b><span>${esc(net.network||'—')}</span></div><div><b>Gateway</b><span>${esc(net.gateway||'—')}</span></div><div><b>Adapter</b><span>${esc(net.adapter||'—')}</span></div><div><b>VPN indicator</b><span>${esc(net.vpn_detected?'Detected: '+net.vpn_adapters.join(', '):'Not detected')}</span></div></div><p class="caption">${esc(net.note)}</p>`)+panel('Traffic counters',`<div class="cyber-kv"><div><b>Source</b><span>${esc(traffic.source||'—')}</span></div><div><b>Bytes received</b><span>${esc(traffic.bytes_recv??'—')}</span></div><div><b>Bytes sent</b><span>${esc(traffic.bytes_sent??'—')}</span></div><div><b>Packet payload capture</b><span>${esc(traffic.captured_payloads?'Enabled':'Disabled')}</span></div></div><p class="caption">Chỉ thống kê bộ đếm giao diện mạng; không bắt hoặc đọc payload gói tin.</p>`)+(isAdmin()?panel('User Security / MFA',table(users,[['User','username'],['Role','role'],['Enabled','enabled',v=>badge(v?'Active':'Disabled')],['MFA','mfa_enabled',v=>badge(v?'Enabled':'Enrollment required')],['Updated','mfa_updated_at']],r=>button('Reset MFA','mfa-reset51',{id:r.id},'danger'))):'')+panel('TLS Certificate Check',cyberWrite()?form('tls-check51-form',input('Registered host/IP','host')+input('Port','port','number',443),'Kiểm tra TLS'):'<p class="caption">Admin/Analyst/Operator có thể kiểm tra TLS trên asset/server đã đăng ký.</p>')+`<div id="tls51-result"></div>`};
actions['mfa-reset51']=async b=>{if(confirm('Reset MFA người dùng này và thu hồi các Web session hiện tại?')){await api('/v51/auth/mfa/reset/'+b.dataset.id,{method:'POST',body:'{}'});toast('Đã reset MFA. Người dùng phải đăng ký lại ở lần đăng nhập kế tiếp.');await go('secpost51')}};
forms['tls-check51-form']=async f=>{const v=vals(f);const r=await api('/v51/tls/check',{method:'POST',body:JSON.stringify({host:v.host,port:Number(v.port||443)})});$('#tls51-result').innerHTML=panel('TLS result',cyberDetails(r))};



pages.compliance53=async()=>{const [c,p,r]=await Promise.all([api('/v51/compliance'),api('/v51/playbooks?limit=500'),(isAdmin()||isAnalyst())?api('/v51/reports/executive'):Promise.resolve(null)]);const s=c.summary||{};const controls=c.controls||[];const playbooks=p||[];return `<div class="cyber-grid"><div class="cyber-card"><small>Controls</small><strong>${esc(s.total||0)}</strong></div><div class="cyber-card"><small>Assessed</small><strong>${esc(s.coverage_pct||0)}%</strong></div><div class="cyber-card"><small>Passed</small><strong>${esc(s.passed||0)}</strong></div><div class="cyber-card"><small>Failed</small><strong>${esc(s.failed||0)}</strong></div></div>`+panel('Compliance Center',table(controls,[['Framework','framework'],['Control','control_id'],['Title','title'],['Status','status',badge],['Owner','owner'],['Updated','updated_at']],x=>(isAdmin()||isAnalyst())?button('Đánh giá','compliance-edit53',{id:x.id,status:x.status,evidence:x.evidence||'',owner:x.owner||''}):''))+panel('Defensive Response Playbooks',`<p class="caption">Playbook 5.3 chỉ là luồng đề xuất/phê duyệt. Không tự động cô lập thiết bị, khóa tài khoản hay chặn IOC.</p>${cyberWrite()?form('playbook53-form',input('Tên playbook','name','text','SOC response')+select('Loại hành động','action_type',['COLLECT_EVIDENCE','NOTIFY_OWNER','ISOLATE_DEVICE','DISABLE_ACCOUNT','BLOCK_IOC'])+input('Target','target','text','',false)+input('Ghi chú','note','text','',false),'Tạo yêu cầu phê duyệt'):''}${table(playbooks,[['ID','id'],['Tên','name'],['Action','action_type'],['Target','target'],['Status','status',badge],['Requested by','requested_by'],['Approved by','approved_by'],['Updated','updated_at']],x=>x.status==='PENDING_APPROVAL'?((isAdmin()?button('Phê duyệt','playbook-approve53',{id:x.id},'primary'):'')+((isAdmin()||isAnalyst())?button('Hủy','playbook-cancel53',{id:x.id},'danger'):'')):'')}`)+(r?panel('Executive Security Report',`<div class="cyber-kv"><div><b>Security Score</b><span>${esc(r.security_score)}/100</span></div><div><b>Open alerts</b><span>${esc(r.open_alerts)}</span></div><div><b>Critical / High</b><span>${esc(r.critical_alerts)} / ${esc(r.high_alerts)}</span></div><div><b>Vulnerability findings</b><span>${esc(r.vulnerability_findings)}</span></div><div><b>Compliance coverage</b><span>${esc(r.compliance?.coverage_pct||0)}%</span></div><div><b>Pending playbooks</b><span>${esc(r.pending_playbooks)}</span></div></div><details><summary>Chi tiết JSON</summary>${cyberDetails(r)}</details>`):'')};
forms['playbook53-form']=async f=>{await api('/v51/playbooks',{method:'POST',body:JSON.stringify(vals(f))});toast('Đã tạo playbook chờ phê duyệt; chưa thực thi hành động từ xa.');await go('compliance53')};
actions['playbook-approve53']=async b=>{if(!confirm('Phê duyệt playbook này? Bản 5.3 chỉ ghi nhận phê duyệt, KHÔNG tự thực thi hành động từ xa.'))return;await api('/v51/playbooks/'+b.dataset.id+'/approve',{method:'POST',body:'{}'});toast('Đã phê duyệt; chưa thực thi từ xa.');await go('compliance53')};
actions['playbook-cancel53']=async b=>{if(!confirm('Hủy playbook này?'))return;await api('/v51/playbooks/'+b.dataset.id+'/cancel',{method:'POST',body:'{}'});toast('Đã hủy playbook');await go('compliance53')};
actions['compliance-edit53']=async b=>{const status=prompt('Trạng thái: NOT_ASSESSED / PASS / PARTIAL / FAIL / COMPLIANT / NON_COMPLIANT',b.dataset.status||'NOT_ASSESSED');if(status===null)return;const evidence=prompt('Evidence / ghi chú đánh giá:',b.dataset.evidence||'');if(evidence===null)return;await api('/v51/compliance/'+b.dataset.id,{method:'PATCH',body:JSON.stringify({status,evidence,owner:state.user?.username||''})});toast('Đã cập nhật compliance control');await go('compliance53')};



pages.threat54=async()=>{const [sum,iocs,matches,rules]=await Promise.all([api('/v54/threat/summary'),api('/v54/threat/iocs'),api('/v54/threat/matches?limit=300'),api('/v54/detection-rules')]);const editor=isAdmin()||isAnalyst();return `<div class="cyber-grid"><div class="cyber-card"><small>Active IOCs</small><strong>${esc(sum.active_iocs||0)}</strong></div><div class="cyber-card"><small>IOC matches / 24h</small><strong>${esc(sum.ioc_matches_24h||0)}</strong></div><div class="cyber-card"><small>Active rules</small><strong>${esc(sum.active_rules||0)}</strong></div><div class="cyber-card"><small>Mode</small><strong>DEFENSIVE</strong></div></div>`+panel('IOC Watchlist',`<p class="caption">Danh sách IOC cục bộ cho IP, domain và SHA-256. SIEM event mới được so khớp tự động; không thực hiện chặn, khai thác hoặc truy cập từ xa.</p>${editor?form('ioc54-form',select('Loại','indicator_type',['IP','DOMAIN','SHA256'],'IP')+input('Indicator','indicator','text')+select('Severity','severity',['LOW','MEDIUM','HIGH','CRITICAL'],'HIGH')+input('Nhãn','label','text','',false)+input('Nguồn','source','text','manual',false)+input('Ghi chú','note','text','',false),'Thêm IOC'):''}${table(iocs,[['Loại','indicator_type'],['Indicator','indicator'],['Mức','severity',cyberSeverity],['Nhãn','label'],['Nguồn','source'],['Enabled','enabled',v=>badge(v?'ON':'OFF')],['Updated','updated_at']],x=>editor?button(x.enabled?'Tắt':'Bật','ioc-toggle54',{id:x.id})+(isAdmin()?button('Xóa','ioc-delete54',{id:x.id},'danger'):''):'')}`)+panel('IOC matches gần đây',table(matches,[['Time','created_at'],['Mức','severity',cyberSeverity],['Type','indicator_type'],['Indicator','indicator'],['Field','matched_field'],['Value','matched_value'],['Event','event_id']]))+panel('Custom Detection Rules',`<p class="caption">Rule 5.4 chỉ dùng điều kiện nguồn, loại sự kiện, severity tối thiểu, chuỗi chứa, ngưỡng và cửa sổ thời gian. Không dùng regex và không thực thi phản ứng tự động.</p>${editor?form('rule54-form',input('Tên rule','name','text','SOC custom rule')+input('Source (để trống = mọi nguồn)','source','text','',false)+input('Event type (để trống = mọi loại)','event_type','text','',false)+select('Severity tối thiểu','min_severity',['INFO','LOW','MEDIUM','HIGH','CRITICAL'],'INFO')+input('Message chứa (tùy chọn)','contains_text','text','',false)+input('Ngưỡng','threshold','number',1)+input('Cửa sổ giây','window_sec','number',300)+select('Alert severity','alert_severity',['MEDIUM','HIGH','CRITICAL'],'HIGH'),'Tạo detection rule'):''}${table(rules,[['Tên','name'],['Source','source'],['Event type','event_type'],['Min severity','min_severity'],['Contains','contains_text'],['Threshold','threshold'],['Window(s)','window_sec'],['Alert','alert_severity',cyberSeverity],['Enabled','enabled',v=>badge(v?'ON':'OFF')]],x=>editor?button(x.enabled?'Tắt':'Bật','rule-toggle54',{id:x.id})+(isAdmin()?button('Xóa','rule-delete54',{id:x.id},'danger'):''):'')}`)};
forms['ioc54-form']=async f=>{await api('/v54/threat/iocs',{method:'POST',body:JSON.stringify(vals(f))});f.reset();toast('Đã thêm IOC vào watchlist');await go('threat54')};
actions['ioc-toggle54']=async b=>{await api('/v54/threat/iocs/'+b.dataset.id+'/toggle',{method:'POST',body:'{}'});toast('Đã cập nhật IOC');await go('threat54')};
actions['ioc-delete54']=async b=>{if(!confirm('Xóa IOC này khỏi watchlist?'))return;await api('/v54/threat/iocs/'+b.dataset.id,{method:'DELETE'});toast('Đã xóa IOC');await go('threat54')};
forms['rule54-form']=async f=>{const v=vals(f);await api('/v54/detection-rules',{method:'POST',body:JSON.stringify({...v,threshold:Number(v.threshold||1),window_sec:Number(v.window_sec||300),enabled:true})});f.reset();toast('Đã tạo detection rule');await go('threat54')};
actions['rule-toggle54']=async b=>{await api('/v54/detection-rules/'+b.dataset.id+'/toggle',{method:'POST',body:'{}'});toast('Đã cập nhật detection rule');await go('threat54')};
actions['rule-delete54']=async b=>{if(!confirm('Xóa detection rule này?'))return;await api('/v54/detection-rules/'+b.dataset.id,{method:'DELETE'});toast('Đã xóa detection rule');await go('threat54')};



pages.cases55=async()=>{const [summary,cases,risks,alerts]=await Promise.all([api('/v55/summary'),api('/v55/cases?status=ALL&limit=500'),api('/v55/risk/assets?limit=1000'),api('/v51/alerts?status=ALL&limit=500')]);const editor=isAdmin()||isAnalyst();const openAlerts=alerts.filter(x=>x.status!=='RESOLVED');return `<div class="cyber-grid"><div class="cyber-card"><small>Open cases</small><strong>${esc(summary.open_cases)}</strong></div><div class="cyber-card"><small>Critical cases</small><strong>${esc(summary.critical_cases)}</strong></div><div class="cyber-card"><small>Open alerts</small><strong>${esc(summary.open_alerts)}</strong></div><div class="cyber-card"><small>Vulnerability findings</small><strong>${esc(summary.vulnerability_findings)}</strong></div></div>`+panel('SOC Case Management',`<p class="caption">Case là hồ sơ điều tra phòng thủ: gom cảnh báo, owner, SLA, evidence và trạng thái xử lý. Không tự thực thi hành động từ xa.</p>${editor?form('case55-form',input('Tiêu đề case','title','text','Điều tra cảnh báo bảo mật')+select('Priority','priority',['LOW','MEDIUM','HIGH','CRITICAL'],'HIGH')+input('Owner','owner','text',state.user?.username||'',false)+input('Asset IP','asset_ip','text','',false)+input('SLA (giờ)','due_hours','number',24,false)+input('Alert ID liên kết (tùy chọn)','alert_id','number','',false)+input('Tóm tắt','summary','text','',false),'Tạo case'):''}${table(cases,[['ID','id'],['Priority','priority',cyberSeverity],['Status','status',badge],['Title','title'],['Asset','asset_ip'],['Owner','owner'],['Alerts','linked_alerts'],['SLA','sla_breached',v=>v?badge('BREACHED'):badge('OK')],['Updated','updated_at']],x=>button('Chi tiết','case-detail55',{id:x.id})+(editor?button('Cập nhật','case-update55',{id:x.id,status:x.status,priority:x.priority,owner:x.owner||''}):''))}`)+panel('Asset Risk',table(risks,[['Asset','asset_ip'],['Risk','risk_score'],['Level','risk_level',cyberSeverity],['Open alerts','open_alerts'],['Vulnerability findings','vulnerability_findings']]))+panel('Open alerts chưa vào case',table(openAlerts.slice(0,100),[['ID','id'],['Mức','severity',cyberSeverity],['Title','title'],['Asset','asset_ip'],['Status','status',badge]]))};
forms['case55-form']=async f=>{const v=vals(f);const body={title:v.title,priority:v.priority,owner:v.owner||'',asset_ip:v.asset_ip||'',summary:v.summary||''};if(v.due_hours)body.due_hours=Number(v.due_hours);if(v.alert_id)body.alert_id=Number(v.alert_id);await api('/v55/cases',{method:'POST',body:JSON.stringify(body)});f.reset();toast('Đã tạo SOC case');await go('cases55')};
actions['case-detail55']=async b=>{const c=await api('/v55/cases/'+b.dataset.id);modal('SOC Case #'+c.id,`<div class="cyber-kv"><div><b>Title</b><span>${esc(c.title)}</span></div><div><b>Status</b><span>${esc(c.status)}</span></div><div><b>Priority</b><span>${esc(c.priority)}</span></div><div><b>Owner</b><span>${esc(c.owner||'—')}</span></div><div><b>Asset</b><span>${esc(c.asset_ip||'—')}</span></div><div><b>Due</b><span>${esc(c.due_at||'—')}</span></div></div><p>${esc(c.summary||'')}</p>${panel('Linked alerts',table(c.alerts||[],[['ID','id'],['Mức','severity',cyberSeverity],['Title','title'],['Asset','asset_ip'],['Status','status',badge]]))}${panel('Case notes',table(c.notes||[],[['Time','created_at'],['Actor','actor'],['Note','note'],['Evidence','evidence_ref']]))}${cyberWrite()?form('case-note55-form',`<input type="hidden" name="case_id" value="${esc(c.id)}">`+input('Ghi chú','note','text')+input('Evidence ref','evidence_ref','text','',false),'Thêm ghi chú'):''}`)};
forms['case-note55-form']=async f=>{const v=vals(f);await api('/v55/cases/'+v.case_id+'/notes',{method:'POST',body:JSON.stringify({note:v.note,evidence_ref:v.evidence_ref||''})});$('#dialog').close();toast('Đã thêm ghi chú');await go('cases55')};
actions['case-update55']=async b=>{const status=prompt('Status: OPEN / INVESTIGATING / CONTAINED / RESOLVED / CLOSED',b.dataset.status||'OPEN');if(status===null)return;const priority=prompt('Priority: LOW / MEDIUM / HIGH / CRITICAL',b.dataset.priority||'MEDIUM');if(priority===null)return;const owner=prompt('Owner:',b.dataset.owner||'');if(owner===null)return;await api('/v55/cases/'+b.dataset.id,{method:'PATCH',body:JSON.stringify({status,priority,owner})});toast('Đã cập nhật case');await go('cases55')};



pages.endpoint58=async()=>{const endpoints=await api('/v58/endpoints');const high=endpoints.filter(x=>['HIGH','CRITICAL'].includes(String(x.risk_level||''))).length;return `<div class="cyber-hero"><div><div class="eyebrow">WEB HOST SECURITY / 5.8</div><h2>Web Host Monitoring</h2><p class="muted">Theo dõi tự động chính Web host đang chạy ứng dụng: CPU, RAM, disk, tiến trình, dịch vụ và trạng thái bảo vệ khả dụng. Không cần cài chương trình trên máy người dùng.</p><div class="toolbar">${button('Làm mới','page',{page:'endpoint58'})}</div></div><div class="score ${high?'amber':'green'}"><strong>${esc(high)}</strong><small>Host risk High/Critical</small></div></div><div class="cyber-grid"><div class="cyber-card"><small>Web hosts</small><strong>${esc(endpoints.length)}</strong></div><div class="cyber-card"><small>Giám sát</small><strong>${endpoints.length?'ACTIVE':'WAITING'}</strong></div><div class="cyber-card"><small>Nguồn</small><strong>SERVER</strong></div><div class="cyber-card"><small>Thiết bị người dùng</small><strong>BROWSER</strong></div></div>`+panel('Web host inventory',table(endpoints,[['Risk','risk_level',cyberSeverity],['Score','risk_score'],['Hostname','hostname'],['IP host','local_ip'],['OS','os_name'],['CPU %','cpu_percent'],['RAM %','memory_percent'],['Disk %','disk_percent'],['Firewall','firewall_status',badge],['Antivirus','antivirus_status',badge],['Last seen','last_seen']],r=>button('Chi tiết','endpoint-detail58',{id:r.endpoint_id})))+panel('Phạm vi Web-only',`<p class="caption">Địa chỉ mạng của điện thoại/PC đang truy cập được tự nhận ở thanh trạng thái và trang Tốc độ & Đường truyền qua kết nối HTTPS. Website không yêu cầu cài thêm tiến trình nền.</p>`)};
actions['endpoint-detail58']=async b=>{const d=await api('/v58/endpoints/'+encodeURIComponent(b.dataset.id)),e=d.endpoint,s=d.samples||[];modal('Endpoint: '+e.hostname,`<div class="cyber-grid"><div class="cyber-card"><small>Risk</small><strong>${esc(e.risk_score)} / ${esc(e.risk_level)}</strong></div><div class="cyber-card"><small>Firewall</small><strong>${esc(e.firewall_status)}</strong></div><div class="cyber-card"><small>Antivirus</small><strong>${esc(e.antivirus_status)}</strong></div><div class="cyber-card"><small>Last seen</small><strong>${esc(e.last_seen)}</strong></div></div><p><b>Lý do risk:</b> ${esc((e.risk_reasons||[]).join(' · ')||'Không có cảnh báo risk.')}</p>${panel('Telemetry gần nhất',table(s.slice(0,50),[['Time','created_at'],['CPU','cpu_percent'],['RAM','memory_percent'],['Disk','disk_percent'],['Processes','process_count'],['Services','service_count'],['Software','software_count'],['Firewall','firewall_status',badge],['Antivirus','antivirus_status',badge]]))}`)};

pages.daily57=async()=>{
  const d=await api('/v57/daily'),rows=d.tasks||[],a=d.daily_auto||{};
  const tone=d.all_clear?'green':rows.some(x=>x.needs_attention&&x.severity==='CRITICAL')?'red':'amber';
  const autoState=a.enabled?(a.running?'ĐANG CHẠY':'ĐANG BẬT'):'ĐANG TẮT';
  const autoTone=a.enabled?(a.last_status==='PARTIAL'?'amber':'green'):'amber';
  const autoButtons=isAdmin()?`${button(a.enabled?'Tắt tự động hoàn thiện':'Bật tự động hoàn thiện','daily-auto-toggle57',{enabled:a.enabled?'1':'0'},a.enabled?'danger':'primary')}${button('Chạy tự động ngay','daily-auto-run57')}`:'';
  const autoStatus=x=>x.auto_status==='AUTO_DONE'?badge('AUTO DONE'):x.auto_status==='NEEDS_HUMAN'?badge('CẦN NGƯỜI XỬ LÝ'):x.auto_status==='CHECKED'?badge('ĐÃ TỰ KIỂM TRA'):badge('CHƯA CHẠY');
  return `<div class="cyber-hero"><div><div class="eyebrow">DAILY SECURITY OPERATIONS / 6.9</div><h2>Việc cần làm hôm nay</h2><p class="muted">Checklist có chế độ tự động hoàn thiện an toàn: Web tự kiểm tra/đồng bộ các tác vụ có thể tự động, nhưng không tự đóng cảnh báo, case, sửa lỗ hổng, bật MFA hay thay đổi cấu hình từ xa.</p><div class="toolbar">${button('SOC Dashboard','page',{page:'soc51'})}${button('Làm mới checklist','page',{page:'daily57'})}${autoButtons}${canAnalyze()?button(d.reviewed_today?'Đã kiểm tra hôm nay':'Đánh dấu đã kiểm tra','daily-reviewed57',{},d.reviewed_today?'':'primary'):''}</div></div><div class="score ${tone}"><strong>${esc(d.attention_items)}</strong><small>Mục cần chú ý</small></div></div>
  <div class="cyber-grid"><div class="cyber-card"><small>Nhóm cần xử lý</small><strong>${esc(d.attention_categories)}</strong></div><div class="cyber-card"><small>Tổng mục</small><strong>${esc(d.attention_items)}</strong></div><div class="cyber-card ${autoTone}"><small>Tự động hoàn thiện</small><strong>${esc(autoState)}</strong></div><div class="cyber-card"><small>Chu kỳ</small><strong>${a.enabled?Math.max(0,Math.ceil((a.next_in_seconds||0)/60))+' phút':'OFF'}</strong></div></div>
  ${panel('Tự động hoàn thiện an toàn',`<div class="toolbar"><span>${badge(autoState)}</span><span class="caption">Mỗi 5 phút: Presence · LAN Discovery · Alert Rules · Incident/RCA · Line Quality · DB Backup</span></div><p class="caption"><b>Lần chạy gần nhất:</b> ${esc(a.last_run_at||'Chưa chạy')} · <b>Kết quả:</b> ${esc(a.last_status||'N/A')} · ${esc(a.last_detail||'')}</p><p class="caption">Mục đã sạch sau kiểm tra sẽ thành <b>AUTO DONE</b>. Mục vẫn có rủi ro sẽ giữ <b>CẦN NGƯỜI XỬ LÝ</b>; hệ thống không che giấu hoặc tự resolve rủi ro.</p>`)}
  ${panel('Checklist ưu tiên',table(rows,[['Mức','severity',cyberSeverity],['Việc cần kiểm tra','title'],['Số lượng','count'],['Rủi ro','needs_attention',v=>v?badge('ACTION'):badge('OK')],['Tự động','auto_status',(_,r)=>autoStatus(r)],['Gợi ý','detail']],r=>r.needs_attention?button('Xử lý ngay','page',{page:r.page},['CRITICAL','HIGH'].includes(r.severity)?'primary':''):button('Xem','page',{page:r.page})))}
  ${panel('Nguyên tắc vận hành',`<p class="caption">${esc(d.note)}</p><p class="caption">Tự động hoàn thiện = tự kiểm tra và chạy tác vụ an toàn; không đồng nghĩa tự đóng sự cố. Đánh dấu "đã kiểm tra" vẫn là xác nhận của người vận hành.</p>${d.reviewed_at?`<p><b>Đã kiểm tra lúc:</b> ${esc(d.reviewed_at)}</p>`:''}`)}`;
};
actions['daily-reviewed57']=async()=>{const r=await api('/v57/daily/reviewed',{method:'POST',body:'{}'});toast(`Đã ghi nhận daily review: ${r.attention_items} mục cần chú ý`);await go('daily57')};
actions['daily-auto-toggle57']=async b=>{const enabled=b.dataset.enabled==='1';const action=enabled?'disable':'enable';const msg=enabled?'Tắt tự động hoàn thiện Việc cần làm hôm nay?':'Bật tự động hoàn thiện an toàn? Web sẽ tự kiểm tra Presence, LAN Discovery, Alert Rules, Incident/RCA, Line Quality và DB Backup mỗi 5 phút; không tự đóng cảnh báo/case hay thay đổi cấu hình.';if(!confirm(msg))return;await api('/v57/daily/auto/'+action,{method:'POST',body:'{}'});toast(enabled?'Đã tắt tự động hoàn thiện.':'Đã bật tự động hoàn thiện.');setTimeout(()=>void go('daily57'),500)};
actions['daily-auto-run57']=async()=>{if(!confirm('Chạy ngay một vòng tự động hoàn thiện an toàn?'))return;const r=await api('/v57/daily/auto/run-now',{method:'POST',body:'{}'});toast(r.started?'Đã bắt đầu tự động hoàn thiện.':'Một vòng tự động đang chạy.');setTimeout(()=>void go('daily57'),900)};

pages.notify56=async()=>{const [st,logs,reports,alerts]=await Promise.all([api('/v56/notifications/status'),api('/v56/notifications/logs?limit=200'),api('/v56/reports/snapshots?limit=100'),api('/v51/alerts?status=ALL&limit=100')]);const editor=isAdmin()||isAnalyst();const channelState=(name,enabled,ready)=>`${name}: ${ready?badge('READY'):enabled?badge('CONFIG INCOMPLETE'):badge('OFF')}`;return `<div class="cyber-grid"><div class="cyber-card"><small>Notification engine</small><strong>${st.enabled?'ON':'OFF'}</strong></div><div class="cyber-card"><small>Sent / 24h</small><strong>${esc(st.sent_24h||0)}</strong></div><div class="cyber-card"><small>Failed / 24h</small><strong>${esc(st.failed_24h||0)}</strong></div><div class="cyber-card"><small>Cooldown</small><strong>${esc(st.cooldown_min||0)}m</strong></div></div>`+panel('Enterprise Notifications',`<p class="caption">5.6 sử dụng cấu hình Email/Telegram đã mã hóa của NetworkAutomation. Trang này không trả token hoặc SMTP password về trình duyệt. HIGH/CRITICAL SOC alerts vẫn dùng notifier nền hiện có; gửi thử/gửi lại luôn cần thao tác rõ ràng.</p><div class="toolbar">${channelState('Email',st.email_enabled,st.email_ready)} ${channelState('Telegram',st.telegram_enabled,st.telegram_ready)} ${button('Mở cấu hình Notifications','page',{page:'notify'})}</div>${isAdmin()?`<div class="toolbar">${button('Test Email','notify-test56',{channel:'EMAIL'})}${button('Test Telegram','notify-test56',{channel:'TELEGRAM'})}</div>`:''}`)+panel('SOC alerts - gửi lại có xác nhận',table(alerts,[['ID','id'],['Mức','severity',cyberSeverity],['Status','status',badge],['Title','title'],['Asset','asset_ip'],['Last','last_seen']],r=>editor&&['HIGH','CRITICAL'].includes(String(r.severity||'').toUpperCase())?button('Gửi thông báo','alert-notify56',{id:r.id}):''))+panel('Delivery log',table(logs,[['Time','created_at'],['Channel','channel'],['Status','status',badge],['Event key','event_key'],['Detail','detail']]))+panel('Security Report Snapshots',`${editor?`<div class="toolbar">${button('Tạo snapshot hiện tại','report-create56',{},'primary')}</div>`:''}<p class="caption">Snapshot lưu các chỉ số SOC tại thời điểm tạo để so sánh/audit. CSV chỉ chứa số liệu và top alerts; không chứa password, token hay secret vault.</p>${table(reports,[['ID','id'],['Time','created_at'],['By','created_by'],['Score','security_score'],['Critical','critical_alerts'],['High','high_alerts'],['Vulns','vulnerability_findings'],['Cases','open_cases'],['SLA breached','sla_breached_cases']],r=>button('Chi tiết','report-view56',{id:r.id})+button('CSV','report-csv56',{id:r.id}))}`)};
actions['notify-test56']=async b=>{const channel=b.dataset.channel;if(!confirm(`Gửi thông báo thử thật qua ${channel}?`))return;const r=await api('/v56/notifications/test',{method:'POST',body:JSON.stringify({channel,confirm_external:true})});toast(`Đã gửi test ${r.channel}`);await go('notify56')};
