// Cybersecurity 5.9 - Network Speed & Line Quality
tr.netspeed59='Tốc độ & Đường truyền';navIcon.netspeed59='⇅';
const netGroup59=groups.find(g=>g[0]==='MẠNG & CHẨN ĐOÁN');if(netGroup59&&!netGroup59[1].includes('netspeed59'))netGroup59[1].push('netspeed59');
function netGrade59(v){const x=String(v||'UNKNOWN').toUpperCase();return badge(x)}
function netProbeView59(stage='Đang chuẩn bị phép đo...',pct=8){return `<div class="net-probe59"><div class="net-radar59"><i></i><i></i><i></i><span>⇅</span></div><strong>Đang kiểm tra đường truyền</strong><small id="net-probe-stage59">${esc(stage)}</small><div class="net-progress59"><i id="net-progress-bar59" style="width:${Math.max(4,Math.min(100,pct))}%"></i></div><div class="net-probe-steps59"><span>Thiết bị</span><span>HTTPS</span><span>Latency</span><span>Jitter/Loss</span></div></div>`}
function lineResultView59(r){const grade=String(r.grade||'UNKNOWN').toUpperCase(),lag=['FAIR','POOR'].includes(grade),browser=r.source==='BROWSER'||r.identity?.source==='BROWSER';return `<div class="net-result59 ${grade.toLowerCase()}"><div class="net-result-grade59"><small>ĐÁNH GIÁ</small><strong>${esc(grade)}</strong></div><div class="net-result-metrics59"><div><small>Latency</small><b>${r.latency_ms==null?'—':esc(r.latency_ms)+' ms'}</b></div><div><small>Jitter</small><b>${r.jitter_ms==null?'—':esc(r.jitter_ms)+' ms'}</b></div><div><small>Packet loss</small><b>${r.packet_loss==null?'—':esc(r.packet_loss)+'%'}</b></div></div></div>${lag&&isAdmin()&&!browser?`<div class="net-lag-alert59"><div><b>Phát hiện dấu hiệu mạng lag</b><span>Hệ thống có thể thử tối ưu cấu hình mạng Windows rồi đo lại trước/sau. Không thể vượt giới hạn gói cước/router/ISP.</span></div>${button('Tối ưu đường truyền','line-optimize59',{},'primary')}</div>`:''}${cyberDetails(r)}`}
function runProbeAnimation59(){let step=0;const stages=[['Đang kiểm tra thiết bị đang mở Web...',16],['Đang đo HTTPS tới Render...',34],['Đang lấy IP công khai...',55],['Đang tính latency và jitter...',73],['Đang đo packet loss...',88],['Đang tổng hợp chất lượng đường truyền...',94]];return setInterval(()=>{const x=stages[Math.min(step++,stages.length-1)],t=document.querySelector('#net-probe-stage59'),b=document.querySelector('#net-progress-bar59');if(t)t.textContent=x[0];if(b)b.style.width=x[1]+'%';},420)}

const browserNet59={lastAuto:0,busy:false};
function browserConnection59(){const c=navigator.connection||navigator.mozConnection||navigator.webkitConnection||{};return {effective_type:String(c.effectiveType||''),downlink_hint:Number.isFinite(Number(c.downlink))?Number(c.downlink):null,rtt_hint:Number.isFinite(Number(c.rtt))?Number(c.rtt):null,save_data:!!c.saveData}}
async function browserPingSeries59(samples=5){const vals=[];let failed=0;for(let i=0;i<samples;i++){const t=performance.now();try{const r=await fetch('/api/v59/browser/ping?x='+Date.now()+'_'+i,{credentials:'same-origin',cache:'no-store',headers:{'Accept':'text/plain'}});if(!r.ok)throw new Error('HTTP '+r.status);await r.text();vals.push(performance.now()-t)}catch{failed++}await new Promise(res=>setTimeout(res,80))}const latency=vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:null;let jitter=null;if(vals.length>1){const mean=latency;jitter=Math.sqrt(vals.reduce((a,b)=>a+Math.pow(b-mean,2),0)/vals.length)}return {latency_ms:latency==null?null:Number(latency.toFixed(2)),jitter_ms:jitter==null?null:Number(jitter.toFixed(2)),packet_loss:Number((failed*100/samples).toFixed(1))}}
async function browserReport59(metrics,testType='BROWSER_LINE'){const conn=browserConnection59();return await api('/v59/browser/report',{method:'POST',body:JSON.stringify({...metrics,...conn,test_type:testType})})}
async function browserLineProbe59({silent=false}={}){if(browserNet59.busy)throw new Error('Đang có phép đo mạng khác chạy.');browserNet59.busy=true;try{const probe=await api('/v59/browser/probe');const metrics=await browserPingSeries59(5);const r=await browserReport59(metrics,'BROWSER_LINE');r.public_ip=probe.public_ip;r.source='BROWSER';return r}finally{browserNet59.busy=false}}
async function browserSpeedProbe59(downloadMB=5,uploadMB=2){if(browserNet59.busy)throw new Error('Đang có phép đo khác chạy.');browserNet59.busy=true;try{const line=await browserPingSeries59(4);const dBytes=Math.max(1,Math.min(8,Number(downloadMB)||5))*1024*1024;let t=performance.now();const dr=await fetch('/api/v59/browser/download?bytes='+dBytes+'&x='+Date.now(),{credentials:'same-origin',cache:'no-store'});if(!dr.ok)throw new Error('DOWNLOAD_HTTP_'+dr.status);const ab=await dr.arrayBuffer();const ds=Math.max((performance.now()-t)/1000,0.001);const down=Number(((ab.byteLength*8/1e6)/ds).toFixed(2));const uBytes=Math.max(1,Math.min(4,Number(uploadMB)||2))*1024*1024;const body=new Uint8Array(uBytes);t=performance.now();const ur=await fetch('/api/v59/browser/upload',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/octet-stream',...(state.csrf?{'X-CSRF-Token':state.csrf}:{})},body});if(!ur.ok){let msg='UPLOAD_HTTP_'+ur.status;try{const d=await ur.json();msg=d.detail||msg}catch{}throw new Error(msg)}await ur.json();const us=Math.max((performance.now()-t)/1000,0.001);const up=Number(((uBytes*8/1e6)/us).toFixed(2));const r=await browserReport59({...line,download_mbps:down,upload_mbps:up},'BROWSER_SPEED');r.source='BROWSER';return r}finally{browserNet59.busy=false}}
function scheduleBrowserAuto59(){if(!cyberWrite())return;const now=Date.now();if(now-browserNet59.lastAuto<60000)return;browserNet59.lastAuto=now;setTimeout(async()=>{try{const r=await browserLineProbe59({silent:true});if(r&&state.page==='netspeed59')await go('netspeed59')}catch{}},350)}

pages.netspeed59=async()=>{const [s,h]=await Promise.all([api('/v59/network/summary'),api('/v59/network/history?limit=100')]);const l=s.latest_line||{},sp=s.latest_speed||{},id=s.identity||{},lag=['FAIR','POOR'].includes(String(l.grade||'').toUpperCase());scheduleBrowserAuto59();return `<div class="cyber-hero"><div><div class="eyebrow">NETWORK QUALITY / WEB</div><h2>Tốc độ mạng & Chất lượng đường truyền</h2><p class="muted">Web tự xác định IP Internet công khai của thiết bị đang mở trang và đo latency, jitter, packet loss, download/upload trực tiếp bằng HTTPS. Không cần cài hoặc chạy chương trình nào trên máy tính hay điện thoại.</p><div class="toolbar">${canWrite()?button('Kiểm tra đường truyền','line-test59',{},'primary'):''}${canWrite()?button('Đo tốc độ trên thiết bị này','speed-test59'):''}${button('Làm mới','page',{page:'netspeed59'})}</div></div><div class="score ${String(l.grade||'').toUpperCase()==='POOR'?'red':String(l.grade||'').toUpperCase()==='FAIR'?'amber':'green'}"><strong>${esc(l.grade||'CHƯA ĐO')}</strong><small>Line quality gần nhất</small></div></div><div class="cyber-grid"><div class="cyber-card"><small>IP Internet công khai</small><strong>${esc(id.local_ip||'-')}</strong></div><div class="cyber-card"><small>Kết nối</small><strong>HTTPS</strong></div><div class="cyber-card"><small>Latency</small><strong>${l.latency_ms==null?'-':esc(l.latency_ms)+' ms'}</strong></div><div class="cyber-card"><small>Jitter</small><strong>${l.jitter_ms==null?'-':esc(l.jitter_ms)+' ms'}</strong></div><div class="cyber-card"><small>Packet loss</small><strong>${l.packet_loss==null?'-':esc(l.packet_loss)+'%'}</strong></div><div class="cyber-card"><small>Download gần nhất</small><strong>${sp.download_mbps==null?'-':esc(sp.download_mbps)+' Mbps'}</strong></div><div class="cyber-card"><small>Upload gần nhất</small><strong>${sp.upload_mbps==null?'-':esc(sp.upload_mbps)+' Mbps'}</strong></div><div class="cyber-card"><small>Chế độ đo</small><strong>WEB / BROWSER</strong></div></div>`+(lag?`<div class="net-lag-banner59"><b>Đường truyền đang ${esc(String(l.grade).toUpperCase())}</b><span>Kết quả được đo trên chính thiết bị đang mở Web. Web không tự thay đổi cấu hình mạng của điện thoại/PC.</span></div>`:'')+`<div class="inline-notice"><b>Web tự kiểm tra mạng đang dùng.</b> IP hiển thị là IP Internet công khai mà kết nối hiện tại dùng để truy cập Render. Mỗi khi đổi Wi‑Fi/4G/5G hoặc nhà mạng, Web sẽ tự cập nhật ở lần kiểm tra tiếp theo.</div>`+panel('Lịch sử đo',table(h,[['Time','created_at'],['Loại','test_type',badge],['Grade','grade',netGrade59],['Latency ms','latency_ms'],['Jitter ms','jitter_ms'],['Loss %','packet_loss'],['Download Mbps','download_mbps'],['Upload Mbps','upload_mbps'],['IP công khai','local_ip']]))+panel('Giới hạn của trình duyệt',`<p class="caption">Website có thể tự nhận IP Internet công khai và đo kết nối HTTPS. Chrome/Safari/Edge không cấp quyền chung cho website đọc IP private 192.168.x.x, gateway, ARP/MAC hoặc quét các thiết bị khác trong LAN; đây là giới hạn bảo mật của trình duyệt, không phải lỗi của Web.</p>`)};

actions['line-test59']=async()=>{modal('Đang kiểm tra đường truyền',netProbeView59());const timer=runProbeAnimation59();try{const r=await browserLineProbe59();clearInterval(timer);const b=document.querySelector('#net-progress-bar59');if(b)b.style.width='100%';toast(`Đường truyền: ${r.grade} · ${r.latency_ms??'-'} ms · loss ${r.packet_loss??'-'}%`);modal('Kết quả kiểm tra đường truyền',lineResultView59(r));await go('netspeed59')}catch(e){clearInterval(timer);throw e}};
actions['speed-test59']=async()=>{if(!confirm('Đo tốc độ trên thiết bị đang mở Web sẽ truyền khoảng 5 MB tải xuống + 2 MB tải lên giữa trình duyệt và Render. Tiếp tục?'))return;modal('Đang đo tốc độ trên thiết bị',netProbeView59('Đang đo trực tiếp từ trình duyệt...',20));const timer=runProbeAnimation59();try{const r=await browserSpeedProbe59(5,2);clearInterval(timer);toast(`Thiết bị hiện tại: Download ${r.download_mbps} Mbps · Upload ${r.upload_mbps??'-'} Mbps`);modal('Kết quả Speed Test',cyberDetails(r));await go('netspeed59')}catch(e){clearInterval(timer);throw e}};

// Compatibility marker for older QA: canWrite()?button('Đo tốc độ WAN'
// 5.9.2: make the daily checklist impossible to miss even when the sidebar group is collapsed.
const dashboardBefore591=pages.dashboard;
pages.dashboard=async()=>{
  const [base,daily]=await Promise.all([dashboardBefore591(),api('/v57/daily').catch(()=>null)]);
  const n=daily?Number(daily.attention_items||0):null;
  const tone=daily&&daily.all_clear?'green':(n&&n>0?'amber':'');
  const summary=daily?`${esc(n)} mục cần chú ý · ${daily.reviewed_today?'Đã kiểm tra':'Chưa kiểm tra hôm nay'}`:'Mở checklist an ninh hằng ngày';
  return `<div class="daily-shortcut591 ${tone}"><div><small>DAILY SECURITY</small><strong>Việc cần làm hôm nay</strong><span>${summary}</span></div>${button('Mở ngay','page',{page:'daily57'},'primary')}</div>`+base;
};
